#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
scan_ai_traces.py — AIGC 痕迹全量扫描（强制门禁脚本）
用法:
    python scan_ai_traces.py <文件或目录> [--report <输出报告路径>]
支持: .txt .md .docx（解包 word/document.xml 复核），目录递归扫描。
退出码: 0=零残留(通过)  1=有残留(禁止交付)  2=参数/IO错误
"""
import sys, os, re, zipfile, json
from pathlib import Path

# AIGC 痕迹变体清单（大小写不敏感，忽略单词内空格）
VARIANTS = [
    "AI生成", "AI 生成", "ai生成", "内容由AI生成", "内容由 AI 生成",
    "由AI创作", "由 AI 创作", "AIGC", "AI写作", "AI 写作",
    "人工智能生成", "智能助手生成", "生成于AI", "生成于 AI", "AI辅助", "AI 辅助",
    "ContentProducer", "content producer", "Generated by AI", "generated by AI",
    "Generated with AI", "Generated using AI", "Produced by AI", "Made with AI",
    "AI-generated", "ai generated", "ChatGPT", "GPT-4", "Claude", "Copilot",
    "DeepSeek", "LLM-generated", "llm generated",
    "仅供参考", "内容由AI生成仅供学习", "本文由AI生成", "以上内容由AI生成",
    "如有雷同纯属AI", "番茄AI标注", "七猫AI标注", "AIGC标注",
]

def normalize_text(text: str) -> str:
    """归一化：统一空白，便于匹配 'AI 生成' 类变体。"""
    return re.sub(r"\s+", "", text) if text else ""

def scan_text(text: str, label: str, hits: list):
    """在单段文本中找变体，命中追加 (label, 位置描述, 关键词)。"""
    norm = normalize_text(text)
    for v in VARIANTS:
        vn = normalize_text(v)
        if not vn:
            continue
        idx = norm.find(vn)
        if idx != -1:
            # 还原到原文本中的近似位置（归一化后位置为字符偏移）
            hits.append({"file": label, "position": idx, "variant": v.strip()})

def scan_docx(path: Path, hits: list):
    """docx: 解包读取 word/document.xml（含隐藏文本、批注所在 body），防止漏检。"""
    try:
        with zipfile.ZipFile(path) as z:
            xml_names = [n for n in z.namelist() if n.startswith("word/") and n.endswith(".xml")]
            for n in xml_names:
                try:
                    xml = z.read(n).decode("utf-8", errors="ignore")
                except Exception:
                    continue
                # 仅提取可见文本区域，降低误报（保留标签内文本即可，变体关键词均为纯文本）
                texts = re.findall(r"<w:t[^>]*>(.*?)</w:t>", xml, flags=re.S)
                joined = "".join(texts)
                scan_text(joined, f"{path.name}:{n}", hits)
    except Exception as e:
        print(f"[ERROR] docx 解包失败 {path}: {e}")
        sys.exit(2)

def scan_file(path: Path, hits: list):
    suffix = path.suffix.lower()
    if suffix == ".docx":
        scan_docx(path, hits)
        return
    try:
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            text = f.read()
        for lineno, line in enumerate(text.splitlines(), 1):
            norm = normalize_text(line)
            for v in VARIANTS:
                if normalize_text(v) and v.strip() and normalize_text(v) in norm:
                    hits.append({"file": f"{path.name}:{lineno}", "position": -1, "variant": v.strip()})
    except Exception as e:
        print(f"[ERROR] 读取失败 {path}: {e}")
        sys.exit(2)

def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(2)
    target = Path(sys.argv[1])
    report_path = None
    if "--report" in sys.argv:
        i = sys.argv.index("--report")
        if i + 1 < len(sys.argv):
            report_path = Path(sys.argv[i + 1])

    files = []
    if target.is_file():
        files = [target]
    elif target.is_dir():
        files = [p for p in target.rglob("*") if p.is_file() and p.suffix.lower() in (".txt", ".md", ".docx")]
    else:
        print(f"[ERROR] 路径不存在: {target}")
        sys.exit(2)

    hits = []
    for f in sorted(files):
        scan_file(f, hits)

    # 去重（同文件同变体只报一次）
    seen = set()
    uniq = []
    for h in hits:
        key = (h["file"], h["variant"])
        if key not in seen:
            seen.add(key)
            uniq.append(h)

    print("=" * 50)
    print(f"AIGC 痕迹扫描报告")
    print(f"范围: {target}")
    print(f"扫描文件数: {len(files)}  命中: {len(uniq)}")
    if uniq:
        print("-" * 50)
        for h in uniq:
            print(f"  [命中] {h['file']} -> {h['variant']}")
    print("=" * 50)
    if uniq:
        print("结论: 有残留，禁止交付。请清理后重扫（重写/转换后必须重扫）。")
        if report_path:
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_path.write_text(
                json.dumps({"date": __import__("datetime").date.today().isoformat(),
                            "scope": str(target), "files": len(files), "hits": uniq}, ensure_ascii=False, indent=2),
                encoding="utf-8")
        sys.exit(1)
    print("结论: 零残留，通过。")
    sys.exit(0)

if __name__ == "__main__":
    main()
